// the photos the about box shows one at a time (the slideshow, in
// index.html), each a jpeg as a data: url. a data: url, not a file beside
// the page, so it can be drawn into a canvas and read back even when the
// page is opened from disk (file://), where a file's image taints the
// canvas. made from the originals with
//   sips -s format jpeg -s formatOptions 60 --resampleHeight 700
// (maine's at formatOptions 75, the first one the page had)
// and base64; the page dithers each to its size and its own few colours
// (js/raster.js).
const ABOUT_PHOTOS = {
  maine: 'data:image/jpeg;base64,',
  portland: 'data:image/jpeg;base64,',
  dc: 'data:image/jpeg;base64,',
  oscar: 'data:image/jpeg;base64,',
};
